public static function rasyti( $order_id ) {
	$order_id = (int) $order_id;
	if ( ! $order_id ) { return; }
	$order = wc_get_order( $order_id );
	if ( ! $order || 'shop_order' !== $order->get_type() ) { return; }

	/* Faktas rasomas VIENA KARTA (planas §3 taisykle 2). */
	if ( $order->get_meta( self::META_IRASYTA ) ) { return; }

	global $wpdb;
	$jau = (int) $wpdb->get_var( $wpdb->prepare(
		'SELECT COUNT(*) FROM ' . self::t_uzsakymai() . ' WHERE uzsakymas_id=%d', $order_id ) );
	if ( $jau ) {
		$order->update_meta_data( self::META_IRASYTA, self::dabar() );
		$order->save();
		return;
	}

	self::uztikrinti_lenteles();

	$aplinka  = self::aplinka();
	$testinis = self::ar_testinis( $order );
	$hash     = self::email_hash( $order );
	$apmoketa = $order->get_date_paid() ? self::utc( $order->get_date_paid() ) : self::dabar();

	/* ---------- klientas: kelintas uzsakymas ---------- */
	list( $nr, $naujas, $dienos ) = self::kliento_eile( $hash, $apmoketa );

	/* ---------- eilutes ---------- */
	$eil = self::surinkti_eilutes( $order );

	$prekiu_suma = 0; $pvm_eiluciu = 0; $savikaina = 0; $dovanu_sav = 0;
	$nuolaidos   = 0; $sandeliai = array();
	/* prekiu_suma_ct = PRIES nuolaida (planas §4.1: marza = prekiu_suma
	   - nuolaidu - savikaina). Jei cia dedtume line_total (jau PO
	   nuolaidos), nuolaida butu atimta DU kartus. Faktuose laikom
	   daugiau informacijos: is bruto visada gali gauti neto, atvirksciai
	   ne. Neto pajamos = prekiu_suma_ct - nuolaidu_ct. */
	foreach ( $eil as $r ) {
		$prekiu_suma += $r['kaina_ct'] + $r['nuolaida_ct'];
		$pvm_eiluciu += $r['pvm_ct'];
		$nuolaidos   += $r['nuolaida_ct'];
		if ( $r['savikaina_ct'] !== null ) {
			if ( $r['dovana'] ) { $dovanu_sav += $r['savikaina_ct']; }
			else { $savikaina += $r['savikaina_ct']; }

