/**
 * Uzpildo `diena` ir perrasо `kaina_reguliari_ct` esamoms eilutems.
 * Idempotentiska: kartojant rezultatas tas pats. Nekeicia pinigu laukus.
 */
public static function migracija_v2( $dry = true ) {
	global $wpdb;
	$u = self::t_uzsakymai(); $e = self::t_eilutes();
	$rez = array( 'dry' => (bool) $dry, 'uzsakymai' => array(), 'eilutes' => array() );

	foreach ( (array) $wpdb->get_results( "SELECT uzsakymas_id, apmoketa_at, diena FROM $u", ARRAY_A ) as $r ) {
		$d = self::verslo_diena( $r['apmoketa_at'] );
		$rez['uzsakymai'][] = array( 'id' => (int) $r['uzsakymas_id'], 'apmoketa_utc' => $r['apmoketa_at'], 'buvo' => $r['diena'], 'tampa' => $d );
		if ( ! $dry ) {
			$wpdb->update( $u, array( 'diena' => $d, 'fakt_versija' => self::FAKT_VERSIJA ), array( 'uzsakymas_id' => (int) $r['uzsakymas_id'] ), array( '%s', '%d' ), array( '%d' ) );
		}
	}

	foreach ( (array) $wpdb->get_results( "SELECT id, uzsakymas_id, preke_id, variacija_id, apmoketa_at, diena, kaina_reguliari_ct, kaina_ct, nuolaida_ct, kiekis FROM $e ORDER BY id", ARRAY_A ) as $r ) {
		$rpid = (int) $r['variacija_id'] ? (int) $r['variacija_id'] : (int) $r['preke_id'];
		$reg_ct = self::reguliari_neto_ct( $rpid );
		$d = self::verslo_diena( $r['apmoketa_at'] );
		$pries_kupona = (int) $r['kiekis'] > 0 ? (int) round( ( (int) $r['kaina_ct'] + (int) $r['nuolaida_ct'] ) / (int) $r['kiekis'] ) : 0;
		$rez['eilutes'][] = array(
			'id' => (int) $r['id'], 'uzs' => (int) $r['uzsakymas_id'], 'preke' => $rpid,
			'reg_buvo' => $r['kaina_reguliari_ct'], 'reg_tampa' => $reg_ct,
			'pries_kupona_isvestine' => $pries_kupona, 'diena' => $d,
		);
		if ( ! $dry ) {
			$wpdb->update( $e,
				array( 'kaina_reguliari_ct' => $reg_ct, 'diena' => $d ),
				array( 'id' => (int) $r['id'] ),
				array( $reg_ct === null ? '%s' : '%d', '%s' ), array( '%d' ) );
		}
	}
	$rez['uzs_sk'] = count( $rez['uzsakymai'] );
	$rez['eil_sk'] = count( $rez['eilutes'] );
	return $rez;
}
